<script setup lang="ts">
import type { Category, PointDraft } from '@/api/tracking'
import CodeExamples from './CodeExamples.vue'
defineProps<{ modelValue: PointDraft; categories: Category[]; projectId: number }>()
const emit=defineEmits<{ 'update:modelValue':[PointDraft] }>(); function patch(m:PointDraft,v:Partial<PointDraft>){emit('update:modelValue',{...m,...v})}
</script>
<template><section class="wizard-form"><h2>协作与发布确认</h2><label>产品负责人<input :value="modelValue.product_owner" @input="patch(modelValue,{product_owner:($event.target as HTMLInputElement).value})"></label><label>开发负责人<input :value="modelValue.developer_owner" @input="patch(modelValue,{developer_owner:($event.target as HTMLInputElement).value})"></label><label>需求地址<input :value="modelValue.requirement_url" @input="patch(modelValue,{requirement_url:($event.target as HTMLInputElement).value})"></label><div class="publish-review"><h3>发布检查</h3><dl><div><dt>分类</dt><dd>{{ categories.find(c=>c.id===modelValue.category_id)?.name || '未选择' }}</dd></div><div><dt>触发规则</dt><dd>{{ modelValue.trigger_timing || '未填写' }}</dd></div><div><dt>指标</dt><dd>{{ modelValue.count_pv?'PV ':'' }}{{ modelValue.count_uv?`UV（${modelValue.uv_mode}）`:'' }}</dd></div><div><dt>平台</dt><dd>{{ modelValue.supported_platforms.join('、') || '未选择' }}</dd></div><div><dt>属性</dt><dd>{{ modelValue.properties.length }} 个</dd></div><div><dt>负责人</dt><dd>{{ modelValue.product_owner || '-' }} / {{ modelValue.developer_owner || '-' }}</dd></div></dl><CodeExamples :project-id="projectId" :point-code="modelValue.code" :platform="modelValue.supported_platforms[0] || 'web'" :properties="modelValue.properties" /></div></section></template>
